package com.kongye.floatball;

import android.content.Context;
import android.graphics.*;
import android.os.*;
import android.view.*;
import java.util.concurrent.ExecutorService;

/** Captures one selected region, appending only newly revealed pixels after each scroll. */
final class AutoScrollCapture {
    interface Listener {boolean append(Bitmap piece);void finished(String reason);}
    private final Context context;private final WindowManager windows;private final ExecutorService worker;private final Listener listener;
    private final Rect area;private final int screenW,screenH;private final Handler main=new Handler(Looper.getMainLooper());
    private Bitmap previous,baseline;private View stop;private boolean active;private int generation,frames;
    AutoScrollCapture(Context c,Rect area,int screenW,int screenH,Bitmap baseline,ExecutorService worker,Listener listener){context=c;windows=OverlayWindows.get(c);this.area=new Rect(area);this.screenW=screenW;this.screenH=screenH;this.baseline=baseline;this.worker=worker;this.listener=listener;}
    void start(){active=true;stop=Ui.symbol(context,"stop","停止自动滚动",()->stop(null));stop.setBackground(Ui.bg(Ui.toolbar(),100,context));stop.setElevation(Ui.dp(context,4));WindowManager.LayoutParams p=new WindowManager.LayoutParams(Ui.dp(context,52),Ui.dp(context,52),WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,PixelFormat.TRANSLUCENT);p.gravity=Gravity.TOP|Gravity.RIGHT;p.x=Ui.dp(context,12);p.y=Ui.dp(context,40);p.setTitle("空叶长截图:停止自动滚动");if(Build.VERSION.SDK_INT>=30)p.setFitInsetsTypes(0);try{windows.addView(stop,p);round(false);}catch(RuntimeException error){stop("自动滚动暂不可用，可继续手动截图");}}
    private boolean current(int id){return active&&generation==id;}
    private void round(boolean scroll){if(!active)return;if(frames>=10){stop("已自动截取 10 屏，可预览或继续手动添加");return;}AssistService service=AssistService.instance;if(service==null){stop("无障碍服务已断开，已保留截取内容");return;}int id=++generation;main.postDelayed(()->{if(current(id))stop("滚动或截图超时，已保留截取内容");},8000);try{if(scroll)service.scrollPage(area,()->capture(id));else capture(id);}catch(RuntimeException error){stop("无法滚动当前页面，可继续手动截图");}}
    private void capture(int id){if(!current(id))return;if(stop!=null)stop.setAlpha(0f);main.postDelayed(()->{if(!current(id))return;AssistService service=AssistService.instance;if(service==null){stop("无障碍服务已断开，已保留截取内容");return;}try{service.captureBitmap((image,error)->{if(!current(id)){if(image!=null)image.recycle();return;}if(stop!=null)stop.setAlpha(1f);if(image==null){stop(error);return;}Bitmap frame=null;try{int left=Math.max(0,Math.round(area.left*image.getWidth()/(float)screenW)),top=Math.max(0,Math.round(area.top*image.getHeight()/(float)screenH)),right=Math.min(image.getWidth(),Math.round(area.right*image.getWidth()/(float)screenW)),bottom=Math.min(image.getHeight(),Math.round(area.bottom*image.getHeight()/(float)screenH));if(right-left<32||bottom-top<32)throw new IllegalArgumentException("small area");frame=Bitmap.createBitmap(image,left,top,right-left,bottom-top);if(frame==image)frame=image.copy(Bitmap.Config.ARGB_8888,false);if(frame.getWidth()>1080){Bitmap resized=Bitmap.createScaledBitmap(frame,1080,Math.max(1,frame.getHeight()*1080/frame.getWidth()),true);frame.recycle();frame=resized;}compare(id,frame);frame=null;}catch(RuntimeException|OutOfMemoryError failure){if(frame!=null&&!frame.isRecycled())frame.recycle();stop("无法处理本屏，请缩小区域或完成已有长图");}finally{image.recycle();}});}catch(RuntimeException error){stop("截图暂不可用，已保留截取内容");}},300);}
    private void compare(int id,Bitmap frame){Bitmap old=previous==null?baseline:previous;boolean first=frames==0;int width=frame.getWidth(),height=frame.getHeight();int[] before=null,after=null;if(old!=null&&!old.isRecycled()&&old.getWidth()==width&&old.getHeight()==height){before=new int[width*height];after=new int[width*height];old.getPixels(before,0,width,0,0,width,height);frame.getPixels(after,0,width,0,0,width,height);}int[] a=before,b=after;worker.execute(()->{int shift;try{shift=a==null?-1:FrameStitcher.findShift(a,b,width,height);}catch(RuntimeException failure){shift=-1;}int amount=shift;main.post(()->accept(id,frame,first,amount));});}
    private void accept(int id,Bitmap frame,boolean first,int shift){if(!current(id)){frame.recycle();return;}if(!first&&shift<=0){frame.recycle();stop(shift==0?"已到页面底部或画面未变化，已保留长图":"画面无法可靠对齐，可继续手动添加");return;}int amount=first&&shift<0?frame.getHeight():shift;try{if(amount>0){Bitmap piece=Bitmap.createBitmap(frame,0,frame.getHeight()-amount,frame.getWidth(),amount);if(piece==frame)piece=frame.copy(Bitmap.Config.ARGB_8888,false);if(!listener.append(piece)){frame.recycle();stop("长图达到张数或尺寸上限，可预览并整理");return;}}if(previous!=null)previous.recycle();previous=frame;baseline=null;frames++;++generation;main.postDelayed(()->round(true),450);}catch(RuntimeException|OutOfMemoryError error){frame.recycle();stop("内存不足，已保留截取内容");}}
    void stop(String reason){if(!active)return;active=false;++generation;if(stop!=null){try{windows.removeViewImmediate(stop);}catch(IllegalArgumentException ignored){}stop=null;}if(previous!=null){previous.recycle();previous=null;}baseline=null;listener.finished(reason);}
}
